#ifndef GARDENER_EVENT_H
#define GARDENER_EVENT_H

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* ---------------------------------------------------------------------
 * Event format.
 *
 * An event is one structured record emitted by a detector when it
 * fires. Events are written to `events.jsonl` (one per line) and can
 * also be streamed to the dashboard in Phase F.
 *
 * The binary event struct is 48 bytes, fixed-size, packed. It has no
 * variable-length text. The human-readable message that goes into the
 * JSONL form is generated by the detector at emit time and carried
 * only in the JSONL representation. The binary form carries pure
 * structured data: which channel, which regime, what value, what
 * threshold, when.
 *
 * Lifecycle:
 *   - A detector observes a condition becoming true:
 *       emits one STARTED event
 *   - The condition persists:
 *       no further events (v1 has no ONGOING)
 *   - The condition clears:
 *       emits one CLEARED event
 *
 * If a detector wants to re-fire (e.g., a spike detector that sees
 * a second spike while the first is still "active"), it emits CLEARED
 * for the first spike followed immediately by STARTED for the second.
 * This keeps the invariant "at most one STARTED per channel per
 * detector is active at once."
 *
 * Multi-channel events (correlation, controller/actuator mismatch)
 * use channel_id = 0xFFFF and put the second channel id in
 * channel_id2. Single-channel events set channel_id2 = 0xFFFF.
 * ------------------------------------------------------------------- */

/* ---- constants ---------------------------------------------------- */

#define EVENT_MAGIC          0x45564E54u   /* "EVNT" */
#define EVENT_VERSION        1
#define EVENT_SIZE           48

#define EVENT_CHANNEL_NONE   0xFFFFu       /* sentinel: no single channel */
#define EVENT_REGIME_NONE    0xFFFFu       /* sentinel: regime unknown */

#define EVENT_MSG_MAX        128           /* max JSONL "msg" length */

/* ---- detector taxonomy -------------------------------------------- */

typedef enum {
    DETECTOR_UNKNOWN      = 0,
    DETECTOR_RANGE        = 1,   /* value outside configured [min,max] */
    DETECTOR_ZSCORE       = 2,   /* value far from baseline mean */
    DETECTOR_FLATLINE     = 3,   /* stddev near zero over a window */
    DETECTOR_ROC          = 4,   /* rate of change outside learned envelope */
    DETECTOR_CORRELATION  = 5,   /* expected covariance broken */
    DETECTOR_MISMATCH     = 6,   /* ctrl_out vs actuator disagree */
} detector_t;

/* ---- severity ----------------------------------------------------- */

typedef enum {
    SEVERITY_INFO     = 0,   /* worth logging, no action */
    SEVERITY_WARN     = 1,   /* likely a problem; notify */
    SEVERITY_CRITICAL = 2,   /* definitely a problem; notify loudly */
} severity_t;

/* ---- lifecycle state --------------------------------------------- */

typedef enum {
    EVENT_STATE_STARTED = 0,   /* condition became true */
    EVENT_STATE_CLEARED = 1,   /* condition became false */
} event_state_t;

/* ---- on-disk / on-wire event struct ------------------------------ */

#pragma pack(push, 1)
typedef struct {
    uint32_t timestamp_ns_lo;   /* lower 32 bits of event time */
    uint32_t timestamp_ns_hi;   /* upper 32 bits of event time */
    uint32_t source_ts_ns_lo;   /* lower 32 bits of packet timestamp */
    uint32_t source_ts_ns_hi;   /* upper 32 bits of packet timestamp */
    uint16_t channel_id;        /* primary channel (or NONE) */
    uint16_t channel_id2;       /* secondary channel (or NONE) */
    uint16_t regime;            /* regime index (or NONE) */
    uint16_t _pad;
    float    observed;          /* value at trigger time */
    float    baseline_mean;     /* baseline mean at trigger time */
    float    baseline_stddev;   /* baseline stddev at trigger time */
    float    threshold;         /* threshold that was crossed */
    uint8_t  detector;          /* detector_t */
    uint8_t  severity;          /* severity_t */
    uint8_t  state;             /* event_state_t */
    uint8_t  version;           /* EVENT_VERSION */
    uint32_t crc;               /* CRC-16/MODBUS low 16 bits, upper 16 zero */
} event_t;
#pragma pack(pop)

/* ---- compile-time invariants -------------------------------------- */

_Static_assert(sizeof(event_t) == EVENT_SIZE,
               "event_t must be exactly EVENT_SIZE bytes");

/* ---- JSONL encoding ----------------------------------------------- */

/* Encode one event as a single JSON line (no trailing newline). The
 * caller supplies `msg` — a human-readable string of up to
 * EVENT_MSG_MAX-1 chars — which is placed in the "msg" field. The
 * numeric fields are copied from `e`.
 *
 * Returns the number of bytes the full encoding requires (which may
 * exceed `cap` on truncation), or -1 on error. Callers detect
 * truncation by comparing the return to `cap`.
 *
 * If `e->state == CLEARED`, the encoder still includes all numeric
 * fields; they reflect the state at the moment the condition cleared,
 * which for most detectors is the same as or similar to the state at
 * STARTED.
 */
int event_to_json(const event_t *e, const char *msg,
                  char *buf, size_t cap);

/* Fill in the timestamp fields from a nanosecond value. Convenience
 * for callers who have a uint64 and don't want to split it manually. */
void event_set_timestamp(event_t *e, uint64_t ts_ns);
void event_set_source_ts(event_t *e, uint64_t ts_ns);

/* Read the split timestamps back. */
uint64_t event_get_timestamp(const event_t *e);
uint64_t event_get_source_ts(const event_t *e);

/* ---- naming helpers ----------------------------------------------- */

/* Human-readable names for enums. Used by the JSONL encoder and by
 * any tool that prints events. Return "?" for unknown values. */
const char *detector_name(detector_t d);
const char *severity_name(severity_t s);
const char *event_state_name(event_state_t st);

#endif /* GARDENER_EVENT_H */